{"security_risk":"MEDIUM","summary":"Create visualization.js implementing bubble chart, legend, linked table", "command":"create","path":"/root/output/js/visualization.js","file_text":"/* global d3 */
(() => {
  const BUBBLE_WIDTH = 660;
  const BUBBLE_HEIGHT = 560;
  const MARGIN = { top: 20, right: 20, bottom: 20, left: 20 };

  const bubbleInnerWidth = BUBBLE_WIDTH - MARGIN.left - MARGIN.right;
  const bubbleInnerHeight = BUBBLE_HEIGHT - MARGIN.top - MARGIN.bottom;
  const cx = bubbleInnerWidth / 2;
  const cy = bubbleInnerHeight / 2;

  const appEl = document.getElementById('app');
  const bubbleEl = document.getElementById('bubble-chart');
  const tableEl = document.getElementById('stock-table');
  const tooltipEl = document.getElementById('tooltip');

  if (!appEl || !bubbleEl || !tableEl || !tooltipEl) {
    // If the container elements are missing, fail silently.
    return;
  }

  const formatMarketCap = (value) => {
    if (value == null || Number.isNaN(value)) return '—';
    const abs = Math.abs(value);
    const fmt = (n, s) => `${n.toFixed(2)}${s}`;
    if (abs >= 1e12) return fmt(value / 1e12, 'T');
    if (abs >= 1e9) return fmt(value / 1e9, 'B');
    if (abs >= 1e6) return fmt(value / 1e6, 'M');
    if (abs >= 1e3) return fmt(value / 1e3, 'K');
    return String(value);
  };

  const stringHash = (s) => {
    let h = 2166136261;
    for (let i = 0; i < s.length; i += 1) {
      h ^= s.charCodeAt(i);
      h = Math.imul(h, 16777619);
    }
    return h >>> 0;
  };

  const hashUnit = (s, salt) => {
    const h = stringHash(`${salt}|${s}`);
    return (h % 10000) / 10000;
  };

  const showTooltip = (event, d) => {
    tooltipEl.innerHTML = `
      <div class="tt-title">${d.ticker}</div>
      <div class="tt-row"><span class="tt-label">Name:</span> ${d.fullName}</div>
      <div class="tt-row"><span class="tt-label">Sector:</span> ${d.sector}</div>
    `;
    tooltipEl.classList.add('visible');
    moveTooltip(event);
  };

  const moveTooltip = (event) => {
    const pad = 12;
    tooltipEl.style.left = `${event.pageX + pad}px`;
    tooltipEl.style.top = `${event.pageY - pad}px`;
  };

  const hideTooltip = () => {
    tooltipEl.classList.remove('visible');
  };

  const loadStockDescriptionsCsv = async () => {
    // Prefer loading the copied file, but fall back to embedded data
    // so the app works when opened via file:// in restrictive browsers.
    try {
      return await d3.text('data/stock-descriptions.csv');
    } catch (e) {
      const embedded = document.getElementById('embedded-stock-csv-b64');
      if (!embedded) throw e;
      const b64 = embedded.textContent.trim();
      const bin = atob(b64);
      const bytes = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i += 1) bytes[i] = bin.charCodeAt(i);
      return new TextDecoder('utf-8').decode(bytes);
    }
  };

  const parseRows = (csvText) => {
    const rows = d3.csvParse(csvText);

    const clean = rows.map((r) => {
      const ticker = (r.ticker || '').trim();
      const sector = (r.sector || '').trim();
      const fullName = (r['full name'] || '').trim();
      const marketCapRaw = (r.marketCap || '').trim();
      const marketCap = marketCapRaw === '' ? null : Number(marketCapRaw);
      const isETF = marketCap == null || Number.isNaN(marketCap) || sector === 'ETF';

      return {
        ticker,
        sector,
        fullName,
        marketCap: isETF ? null : marketCap,
        isETF,
      };
    });

    return clean
      .filter((d) => d.ticker)
      .sort((a, b) => d3.ascending(a.ticker, b.ticker));
  };

  const buildSectorPalette = (sectors) => {
    const palette = []
      .concat(d3.schemeTableau10)
      .concat(d3.schemeSet3)
      .concat(d3.schemePaired);
    const colors = sectors.map((_, i) => palette[i % palette.length]);
    return d3.scaleOrdinal(sectors, colors);
  };

  const buildSectorCenters = (sectors) => {
    const R = 140;
    const centers = new Map();
    const ordered = sectors.slice().sort(d3.ascending);
    ordered.forEach((s, i) => {
      const angle = (2 * Math.PI * i) / ordered.length - Math.PI / 2;
      centers.set(s, {
        x: cx + R * Math.cos(angle),
        y: cy + R * Math.sin(angle),
      });
    });
    return centers;
  };

  const render = async () => {
    const csvText = await loadStockDescriptionsCsv();
    const data = parseRows(csvText);

    const sectors = Array.from(new Set(data.map((d) => d.sector))).sort(d3.ascending);
    const color = buildSectorPalette(sectors);
    const sectorCenters = buildSectorCenters(sectors);

    const capValues = data
      .filter((d) => !d.isETF && d.marketCap != null && !Number.isNaN(d.marketCap))
      .map((d) => d.marketCap);

    const capExtent = d3.extent(capValues);
    const radiusScale = d3
      .scaleSqrt()
      .domain([capExtent[0] ?? 0, capExtent[1] ?? 1])
      .range([14, 46]);

    const ETF_R = 18;

    const nodes = data.map((d) => {
      const r = d.isETF ? ETF_R : radiusScale(d.marketCap);
      const sc = sectorCenters.get(d.sector) ?? { x: cx, y: cy };

      const jitterX = (hashUnit(d.ticker, 'x') - 0.5) * 60;
      const jitterY = (hashUnit(d.ticker, 'y') - 0.5) * 60;

      return {
        ...d,
        r,
        x: sc.x + jitterX,
        y: sc.y + jitterY,
      };
    });

    // --- Bubble chart ---
    bubbleEl.innerHTML = '';
    const svg = d3
      .select(bubbleEl)
      .append('svg')
      .attr('width', BUBBLE_WIDTH)
      .attr('height', BUBBLE_HEIGHT)
      .attr('viewBox', `0 0 ${BUBBLE_WIDTH} ${BUBBLE_HEIGHT}`)
      .attr('role', 'img')
      .attr('aria-label', 'Bubble chart of stocks clustered by sector');

    const g = svg.append('g').attr('transform', `translate(${MARGIN.left},${MARGIN.top})`);

    const sim = d3
      .forceSimulation(nodes)
      .force('center', d3.forceCenter(cx, cy))
      .force(
        'x',
        d3
          .forceX((d) => (sectorCenters.get(d.sector) ?? { x: cx }).x)
          .strength(0.22),
      )
      .force(
        'y',
        d3
          .forceY((d) => (sectorCenters.get(d.sector) ?? { y: cy }).y)
          .strength(0.22),
      )
      .force('collide', d3.forceCollide((d) => d.r + 1).iterations(2))
      .force('charge', d3.forceManyBody().strength(-6))
      .stop();

    for (let i = 0; i < 260; i += 1) sim.tick();

    const nodeG = g
      .append('g')
      .attr('class', 'nodes')
      .selectAll('g.node')
      .data(nodes, (d) => d.ticker)
      .join('g')
      .attr('class', 'node')
      .attr('data-ticker', (d) => d.ticker)
      .attr('transform', (d) => `translate(${d.x},${d.y})`)
      .on('mouseover', function (event, d) {
        if (d.isETF) return;
        showTooltip(event, d);
      })
      .on('mousemove', function (event, d) {
        if (d.isETF) return;
        moveTooltip(event);
      })
      .on('mouseout', function (event, d) {
        if (d.isETF) return;
        hideTooltip();
      });

    nodeG
      .append('circle')
      .attr('r', (d) => d.r)
      .attr('fill', (d) => color(d.sector))
      .attr('fill-opacity', 0.88);

    nodeG
      .append('text')
      .attr('class', 'node-label')
      .attr('text-anchor', 'middle')
      .attr('dy', '0.35em')
      .text((d) => d.ticker)
      .style('font-size', (d) => `${Math.max(9, Math.min(14, d.r * 0.55))}px`);

    // Legend
    const legend = g.append('g').attr('class', 'legend').attr('transform', 'translate(0,0)');
    const legendItem = legend
      .selectAll('g.legend-item')
      .data(sectors)
      .join('g')
      .attr('class', 'legend-item')
      .attr('transform', (d, i) => `translate(0,${i * 18})`);

    legendItem
      .append('rect')
      .attr('x', 0)
      .attr('y', 0)
      .attr('width', 12)
      .attr('height', 12)
      .attr('fill', (d) => color(d));

    legendItem
      .append('text')
      .attr('x', 18)
      .attr('y', 10)
      .text((d) => d);

    // --- Table ---
    tableEl.innerHTML = '';

    const table = d3.select(tableEl).append('table').attr('class', 'data-table');

    const thead = table.append('thead');
    const tbody = table.append('tbody');

    thead
      .append('tr')
      .selectAll('th')
      .data(['Ticker symbol', 'Full company name', 'Sector', 'Market cap'])
      .join('th')
      .text((d) => d);

    const rows = tbody
      .selectAll('tr')
      .data(nodes, (d) => d.ticker)
      .join('tr')
      .attr('class', 'table-row')
      .attr('data-ticker', (d) => d.ticker);

    rows
      .selectAll('td')
      .data((d) => [
        { key: 'ticker', value: d.ticker },
        { key: 'fullName', value: d.fullName },
        { key: 'sector', value: d.sector },
        { key: 'marketCap', value: formatMarketCap(d.marketCap) },
      ])
      .join('td')
      .attr('class', (d) => `col-${d.key}`)
      .text((d) => d.value);

    // --- Linked selection ---
    let selectedTicker = null;

    const updateSelection = (ticker) => {
      selectedTicker = ticker;

      g.selectAll('g.node')
        .classed('selected', (d) => d.ticker === selectedTicker)
        .classed('dimmed', (d) => selectedTicker != null && d.ticker !== selectedTicker);

      tbody
        .selectAll('tr.table-row')
        .classed('selected', (d) => d.ticker === selectedTicker)
        .classed('dimmed', (d) => selectedTicker != null && d.ticker !== selectedTicker);

      if (selectedTicker) {
        const rowNode = tbody.select(`tr.table-row[data-ticker="${selectedTicker}"]`).node();
        if (rowNode) rowNode.scrollIntoView({ block: 'nearest' });
      }
    };

    nodeG.on('click', (event, d) => {
      event.stopPropagation();
      updateSelection(d.ticker === selectedTicker ? null : d.ticker);
    });

    rows.on('click', (event, d) => {
      event.stopPropagation();
      updateSelection(d.ticker === selectedTicker ? null : d.ticker);
    });

    document.addEventListener('click', (event) => {
      // Click on empty space clears selection.
      if (!appEl.contains(event.target)) return;
      const isInNode = !!event.target.closest('g.node');
      const isInRow = !!event.target.closest('tr.table-row');
      if (!isInNode && !isInRow) updateSelection(null);
    });
  };

  render().catch((err) => {
    // Basic fallback: show error in the page.
    const pre = document.createElement('pre');
    pre.className = 'error';
    pre.textContent = `Failed to render visualization:\n${String(err)}`;
    appEl.appendChild(pre);
  });
})();
"}

