      .selectAll('g.legend-item')
      .data(sectors)
      .join('g')
      .attr('class', 'legend-item')
      .attr('transform', (d, i) => `translate(0,${i * 18})`);

    legendItem
      .append('rect')
      .attr('x', 0)
      .attr('y', 0)
      .attr('width', 12)
      .attr('height', 12)
      .attr('fill', (d) => color(d));

    legendItem
      .append('text')
      .attr('x', 18)
      .attr('y', 10)
      .text((d) => d);

