{"security_risk":"MEDIUM","summary":"Create CSS styling for layout, tooltip, table, selection highlights","command":"create","path":"/root/output/css/style.css","file_text":":root {
  --bg: #0b1020;
  --panel: #121a33;
  --text: #e9eefc;
  --muted: #b9c3e6;
  --grid: rgba(233, 238, 252, 0.12);
  --accent: #ffd166;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
}

header {
  padding: 16px 20px;
  border-bottom: 1px solid var(--grid);
}

header h1 {
  margin: 0;
  font-size: 18px;
  font-weight: 650;
}

header p {
  margin: 6px 0 0;
  color: var(--muted);
  font-size: 13px;
}

#app {
  padding: 16px 20px 22px;
}

.layout {
  display: flex;
  gap: 16px;
  align-items: flex-start;
}

.panel {
  background: var(--panel);
  border: 1px solid var(--grid);
  border-radius: 10px;
  overflow: hidden;
}

#bubble-chart.panel {
  flex: 0 0 auto;
}

#stock-table.panel {
  flex: 1 1 auto;
  max-height: 560px;
  overflow: auto;
}

svg {
  display: block;
}

.node circle {
  stroke: rgba(255, 255, 255, 0.18);
  stroke-width: 1;
}

.node.selected circle {
  stroke: var(--accent);
  stroke-width: 3;
}

.node.dimmed {
  opacity: 0.35;
}

.node-label {
  fill: #0b1020;
  font-weight: 700;
  pointer-events: none;
}

.legend text {
  fill: var(--text);
  font-size: 12px;
}

.data-table {
  width: 100%;
  border-collapse: collapse;
}

.data-table thead th {
  position: sticky;
  top: 0;
  background: #0f1730;
  z-index: 1;
  text-align: left;
  padding: 10px 10px;
  font-size: 12px;
  color: var(--muted);
  border-bottom: 1px solid var(--grid);
}

.data-table tbody td {
  padding: 9px 10px;
  border-bottom: 1px solid rgba(233, 238, 252, 0.08);
  font-size: 13px;
}

.data-table tbody tr:hover {
  background: rgba(255, 255, 255, 0.04);
  cursor: pointer;
}

.table-row.selected {
  background: rgba(255, 209, 102, 0.18);
}

.table-row.dimmed {
  opacity: 0.45;
}

.col-marketCap {
  font-variant-numeric: tabular-nums;
}

.tooltip {
  position: absolute;
  pointer-events: none;
  opacity: 0;
  transform: translateY(2px);
  transition: opacity 120ms linear;
  padding: 10px 12px;
  background: rgba(0, 0, 0, 0.86);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 8px;
  color: #fff;
  min-width: 220px;
  z-index: 1000;
}

.tooltip.visible {
  opacity: 1;
}

.tt-title {
  font-weight: 800;
  margin-bottom: 6px;
}

.tt-row {
  font-size: 12px;
  color: rgba(255, 255, 255, 0.92);
  line-height: 1.35;
}

.tt-label {
  color: rgba(255, 255, 255, 0.72);
}

.error {
  background: rgba(255, 70, 70, 0.1);
  border: 1px solid rgba(255, 70, 70, 0.25);
  padding: 12px;
  border-radius: 10px;
  color: #ffd0d0;
  white-space: pre-wrap;
}

@media (max-width: 1100px) {
  .layout {
    flex-direction: column;
  }
  #stock-table.panel {
    max-height: none;
  }
}
"}

